package forth

import (
	"errors"
	"strconv"
	"strings"
)

type word func(e *evaluator) error

type evaluator struct {
	stack []int
	words map[string]word
}

func Forth(input []string) ([]int, error) {
	e := &evaluator{
		stack: []int{},
		words: map[string]word{
			"+": func(e *evaluator) error {
				b, a, err := e.pop2()
				if err != nil {
					return err
				}
				e.stack = append(e.stack, a+b)
				return nil
			},
			"-": func(e *evaluator) error {
				b, a, err := e.pop2()
				if err != nil {
					return err
				}
				e.stack = append(e.stack, a-b)
				return nil
			},
			"*": func(e *evaluator) error {
				b, a, err := e.pop2()
				if err != nil {
					return err
				}
				e.stack = append(e.stack, a*b)
				return nil
			},
			"/": func(e *evaluator) error {
				b, a, err := e.pop2()
				if err != nil {
					return err
				}
				if b == 0 {
					return errors.New("division by zero")
				}
				e.stack = append(e.stack, a/b)
				return nil
			},
			"dup": func(e *evaluator) error {
				a, err := e.pop1()
				if err != nil {
					return err
				}
				e.stack = append(e.stack, a, a)
				return nil
			},
			"drop": func(e *evaluator) error {
				_, err := e.pop1()
				return err
			},
			"swap": func(e *evaluator) error {
				b, a, err := e.pop2()
				if err != nil {
					return err
				}
				e.stack = append(e.stack, b, a)
				return nil
			},
			"over": func(e *evaluator) error {
				b, a, err := e.pop2()
				if err != nil {
					return err
				}
				e.stack = append(e.stack, a, b, a)
				return nil
			},
		},
	}
	for _, line := range input {
		if err := e.run(line); err != nil {
			return nil, err
		}
	}
	return e.stack, nil
}

func (e *evaluator) run(line string) error {
	defining := false
	needName := false
	var name string
	var def []word
	for _, tok := range strings.Fields(line) {
		if defining {
			if needName {
				if isNumber(tok) {
					return errors.New("cannot define a number")
				}
				name = strings.ToLower(tok)
				needName = false
				continue
			}
			if tok == ";" {
				e.words[name] = func(e *evaluator) error {
					for _, w := range def {
						if err := w(e); err != nil {
							return err
						}
					}
					return nil
				}
				defining = false
				continue
			}
			w, err := e.resolve(tok)
			if err != nil {
				return err
			}
			def = append(def, w)
			continue
		}
		if tok == ":" {
			defining = true
			needName = true
			continue
		}
		if isNumber(tok) {
			n, err := strconv.Atoi(tok)
			if err != nil {
				return err
			}
			e.stack = append(e.stack, n)
			continue
		}
		w, err := e.resolve(tok)
		if err != nil {
			return err
		}
		if err := w(e); err != nil {
			return err
		}
	}
	if defining {
		return errors.New("unterminated definition")
	}
	return nil
}

func (e *evaluator) resolve(tok string) (word, error) {
	w, ok := e.words[strings.ToLower(tok)]
	if !ok {
		return nil, errors.New("undefined operation")
	}
	return w, nil
}

func (e *evaluator) pop1() (int, error) {
	if len(e.stack) < 1 {
		return 0, errors.New("empty stack")
	}
	a := e.stack[len(e.stack)-1]
	e.stack = e.stack[:len(e.stack)-1]
	return a, nil
}

func (e *evaluator) pop2() (b, a int, err error) {
	if len(e.stack) < 2 {
		return 0, 0, errors.New("not enough values on the stack")
	}
	a = e.stack[len(e.stack)-1]
	b = e.stack[len(e.stack)-2]
	e.stack = e.stack[:len(e.stack)-2]
	return b, a, nil
}

func isNumber(tok string) bool {
	s := tok
	if s[0] == '-' {
		if len(s) == 1 {
			return false
		}
		s = s[1:]
	}
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

